// Pipeline Configuration
// Commands run via: docker exec mamba_python_worker python ...

const config = {
  // Symbols to process
  symbols: ($env.DEFAULT_SYMBOLS || 'AAPL,MSFT,NVDA').split(',').map(s => s.trim()),

  // Horizon (trading days)
  horizon: parseInt($env.DEFAULT_HORIZON || '63'),

  // Walk-forward window settings
  wf_start: $env.WF_START || '2010-07-02',
  wf_end: $env.WF_END || '2025-07-01',
  wf_train_years: parseInt($env.WF_TRAIN_YEARS || '5'),
  wf_step_days: parseInt($env.WF_STEP_DAYS || '126'),

  // Optuna settings
  optuna_trials: parseInt($env.OPTUNA_TRIALS || '100'),

  // Docker exec prefix (runs in python-worker container)
  docker_exec: 'docker exec mamba_python_worker',

  // Paths (inside python-worker container)
  workspace: '/mamba_workspace',
  python: 'python',

  // Output paths
  cache_features: '/mamba_workspace/cache/features',
  artifacts_stage_a: '/mamba_workspace/artifacts/stage_a',
  artifacts_optuna: '/mamba_workspace/artifacts/optuna_studies',
  artifacts_backtests: '/mamba_workspace/artifacts/backtests',

  // Run ID
  run_id: new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
};

return [{ json: config }];

// STEP 1: dagster_prep_families - Generate feature caches via Dagster
// Output: cache/features/<SYMBOL>_h<H>_merged.parquet

const config = $('Pipeline Config').first().json;
const symbol = $input.item.json.symbols || $input.item.json;

// Build dagster job execute command for prep_families_job
// Uses partition key format: symbol=<SYM>|horizon=<H>
const partitionKey = `symbol=${symbol}|horizon=${config.horizon}`;

const dagsterCmd = [
  `cd ${config.workspace} &&`,
  `DAGSTER_PREP_WF_START=${config.wf_start}`,
  `DAGSTER_PREP_WF_END=${config.wf_end}`,
  `DAGSTER_PREP_WF_TRAIN_YEARS=${config.wf_train_years}`,
  `DAGSTER_PREP_WF_STEP_DAYS=${config.wf_step_days}`,
  `DAGSTER_PREP_WRITE_MERGED=yes`,
  `DAGSTER_PREP_MODE=stage-b`,
  `${config.python} -m dagster job execute`,
  `-m dagster_prep_families.definitions`,
  `-j prep_families_job`,
  `--partition "${partitionKey}"`
].join(' ');

const cmd = `${config.docker_exec} bash -c "${dagsterCmd}"`;

return {
  json: {
    symbol: symbol,
    horizon: config.horizon,
    step: 'dagster_prep_families',
    command: cmd,
    output_path: `${config.cache_features}/${symbol}_h${config.horizon}_merged.parquet`,
    config: config
  }
};

// Validate dagster prep_families output

const input = $input.item.json;
const exitCode = $input.item.json.exitCode || 0;
const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';

let success = (exitCode === 0);
let errorMessage = '';

if (!success) {
  errorMessage = stderr.substring(0, 500) || 'dagster prep_families_job failed with non-zero exit';
}

return {
  json: {
    ...input,
    prep_families_success: success,
    prep_families_error: errorMessage,
    step: 'validate_prep'
  }
};

// STEP 2: stage_a_selector.py - Produce best family weights
// Input: Reads from cache/features/<SYMBOL>_h<H>_merged.parquet
// Output: artifacts/stage_a/<SYMBOL>_h<H>/family_weights_best.json

const input = $input.item.json;
const config = input.config;
const symbol = input.symbol;

const outdir = `${config.artifacts_stage_a}/${symbol}_h${config.horizon}`;

const pythonCmd = [
  `cd ${config.workspace} &&`,
  `${config.python} tools/stage_a_selector.py`,
  `--symbol ${symbol}`,
  `--horizon ${config.horizon}`,
  `--start ${config.wf_start}`,
  `--end ${config.wf_end}`,
  `--wf-start ${config.wf_start}`,
  `--wf-end ${config.wf_end}`,
  `--wf-train-years ${config.wf_train_years}`,
  `--outdir ${outdir}`,
  `--universe-mode global`,
  `--selector-method legacy_optuna`,
  `--proxy-time-adaptive`
].join(' ');

const cmd = `${config.docker_exec} bash -c "${pythonCmd}"`;

return {
  json: {
    ...input,
    step: 'stage_a_selector',
    command: cmd,
    stage_a_outdir: outdir,
    weights_path: `${outdir}/family_weights_best.json`
  }
};

// Validate Stage-A output

const input = $input.item.json;
const exitCode = $input.item.json.exitCode || 0;
const stderr = $input.item.json.stderr || '';

let success = (exitCode === 0);
let errorMessage = '';

if (!success) {
  errorMessage = stderr.substring(0, 500) || 'stage_a_selector failed';
}

return {
  json: {
    ...input,
    stage_a_success: success,
    stage_a_error: errorMessage,
    step: 'validate_stage_a'
  }
};

// STEP 3: run_stage_b_stateful_phase2.py - Train Mamba model
// Input: cache/features/<SYMBOL>_h<H>_merged.parquet + family_weights_best.json
// Output: artifacts/optuna_studies/<study_name>.db

const input = $input.item.json;
const config = input.config;
const symbol = input.symbol;

const studyName = `phase2_v16_full_h${config.horizon}_${symbol}`;
const studyDb = `${config.artifacts_optuna}/${studyName}__label_base.db`;

const pythonCmd = [
  `cd ${config.workspace} &&`,
  `${config.python} tools/run_stage_b_stateful_phase2.py`,
  `--symbol ${symbol}`,
  `--horizon ${config.horizon}`,
  `--search-mode full`,
  `--n-trials ${config.optuna_trials}`,
  `--study-name ${studyName}`,
  `--study-db ${studyDb}`,
  `--phase2-family-weights-path ${input.weights_path}`,
  `--universe-mode full`,
  `--preset research`,
  `--train-start ${config.wf_start}`,
  `--train-end ${config.wf_end}`
].join(' ');

const cmd = `${config.docker_exec} bash -c "${pythonCmd}"`;

return {
  json: {
    ...input,
    step: 'stage_b_phase2',
    command: cmd,
    study_name: studyName,
    study_db: studyDb
  }
};

// Parse Stage-B results

const input = $input.item.json;
const exitCode = $input.item.json.exitCode || 0;
const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';

let success = (exitCode === 0);
let bestSharpe = null;
let bestTrial = null;
let errorMessage = '';

// Parse Optuna output
const sharpeMatch = stdout.match(/Best value[:\s]*([\d.-]+)/i);
const trialMatch = stdout.match(/Best trial[:\s]*(\d+)/i);

if (sharpeMatch) bestSharpe = parseFloat(sharpeMatch[1]);
if (trialMatch) bestTrial = parseInt(trialMatch[1]);

if (!success) {
  errorMessage = stderr.substring(0, 500) || 'Stage-B training failed';
}

return {
  json: {
    symbol: input.symbol,
    horizon: input.horizon,
    study_name: input.study_name,
    study_db: input.study_db,
    merged_parquet: input.output_path,
    weights_path: input.weights_path,
    stage_b_success: success,
    stage_b_error: errorMessage,
    best_sharpe: bestSharpe,
    best_trial: bestTrial,
    run_id: input.config.run_id,
    step: 'complete'
  }
};

// Generate final summary report

const results = $input.all().map(item => item.json);

const summary = {
  run_id: results[0]?.run_id || 'unknown',
  completed_at: new Date().toISOString(),
  total_symbols: results.length,
  successful: results.filter(r => r.stage_b_success !== false).length,
  failed: results.filter(r => r.stage_b_success === false || r.stage_a_success === false || r.prep_families_success === false).length,
  results: results.map(r => ({
    symbol: r.symbol,
    horizon: r.horizon,
    success: r.stage_b_success,
    best_sharpe: r.best_sharpe,
    best_trial: r.best_trial,
    error: r.stage_b_error || r.stage_a_error || r.prep_families_error || null
  }))
};

// Average Sharpe
const validSharpes = summary.results.filter(r => r.best_sharpe !== null).map(r => r.best_sharpe);
summary.avg_sharpe = validSharpes.length > 0 
  ? (validSharpes.reduce((a, b) => a + b, 0) / validSharpes.length).toFixed(4)
  : null;

return [{ json: summary }];

// Log prep_families failure
const input = $input.item.json;
return {
  json: {
    symbol: input.symbol,
    horizon: input.horizon,
    step: 'prep_families',
    success: false,
    error: input.prep_families_error,
    run_id: input.config?.run_id
  }
};

// Log Stage-A failure
const input = $input.item.json;
return {
  json: {
    symbol: input.symbol,
    horizon: input.horizon,
    step: 'stage_a_selector',
    success: false,
    error: input.stage_a_error,
    run_id: input.config?.run_id
  }
};
